**instantsearch.js**

```javascript
search = instantsearch({
  appId: 'XXX',
  apiKey: 'YYY',
  indexName: 'instantsearch_index'
});
search.start();
```

**autocomplete.js**

```javascript
    var client = algoliasearch('XXX', 'YYY');
    var index = client.initIndex('autocomplete_index');
    $('#main-search-form .form-control').autocomplete({ hint: true }, [
        {
          source: $.fn.autocomplete.sources.hits(index, { hitsPerPage: 10 }),
          displayKey: 'name',
          templates: {
            suggestion: function(suggestion) {
              return suggestion._highlightResult.name.value;
            }
          }
        }
    ]).on('autocomplete:selected', function(event, suggestion, dataset) {
        search.helper.setQuery(suggestion.name).search();
    });
```
